/** Tiny SOURCE file controls; metadata is synthetic, no process/browser/GPU. */
import test from'node:test';import assert from'node:assert/strict';import{mkdtemp,chmod,open,rename,unlink,rmdir,rm,readFile,stat}from'node:fs/promises';import os from'node:os';import path from'node:path';import{createHash}from'node:crypto';
import{createMetadataSinkFactory}from'./capture-files.mjs';import{METADATA_CAPTURE_ABI}from'./capture-contract.mjs';
const sha=b=>createHash('sha256').update(b).digest('hex'),operations={mkdtemp,chmod,open,rename,unlink,rmdir,statfs:async()=>({bavail:6n*1024n**3n,bsize:1n})};
const header=bytes=>({abi:METADATA_CAPTURE_ABI,id:'metadata-file-unit',total:bytes.length,chunkBytes:256,hash:sha(bytes)});
test('metadata sink shares nofollow random file lifecycle with exact256byte writes and verification',async()=>{
 const root=await mkdtemp(path.join(os.tmpdir(),'aurialis-metadata-source-'));try{const bytes=Buffer.from('{"synthetic":"not actual hardware"}'),h=header(bytes);let reads=0;const io={...operations,async open(...args){const file=await open(...args);return new Proxy(file,{get(target,key){if(key==='read')return async(buffer,offset,length,position)=>{assert.ok(buffer.byteLength<=256&&length<=256);reads++;return target.read(buffer,offset,length,position);};const value=Reflect.get(target,key,target);return typeof value==='function'?value.bind(target):value;}});}};const file=createMetadataSinkFactory(root,io)(h);await file.acquire();await assert.rejects(file.write(Buffer.alloc(257),0),/geometry/);await file.write(bytes,0);const result=await file.finish();assert.equal(path.basename(result.path),'adapter-metadata.json');assert.equal((await stat(result.path)).mode&0o777,0o600);assert.deepEqual(await readFile(result.path),bytes);assert.equal(reads,1);await file.abort();await file.abort();}finally{await rm(root,{recursive:true,force:true});}
});
test('metadata reader failure plus close failure preserve both and retain retryable handle',async()=>{
 const root=await mkdtemp(path.join(os.tmpdir(),'aurialis-metadata-source-'));try{const bytes=Buffer.from('{}');let reading=false,closeFails=true;const io={...operations,async open(...args){const target=await open(...args);const readonly=(args[1]&3)===0;return new Proxy(target,{get(file,key){if(readonly&&key==='read')return async()=>{reading=true;throw new Error('original verification read');};if(readonly&&key==='close')return async()=>{if(closeFails)throw new Error('reader close unconfirmed');return file.close();};const value=Reflect.get(file,key,file);return typeof value==='function'?value.bind(file):value;}});}};const file=createMetadataSinkFactory(root,io)(header(bytes));await file.acquire();await file.write(bytes,0);await assert.rejects(file.finish(),error=>error instanceof AggregateError&&error.errors[0].message==='original verification read'&&error.errors[1].message==='reader close unconfirmed');assert.equal(reading,true);closeFails=false;assert.deepEqual(await file.abort(),{closed:true});}finally{await rm(root,{recursive:true,force:true});}
});
